private function requirementFieldsFromCandidate(array$c,array$input):array{$statement=$this->noPhi($this->text(['statement'=>$input['requirement_text']??$c['statement']??''],'statement',5000,true));$payer=$this->text(['payer'=>$input['payer']??$c['publisher']??''],'payer',191,false);if($payer===''){$payer='Unknown payer';}$topic=$this->text(['topic'=>$input['topic']??$c['section_label']??''],'topic',191,false);if($topic===''||strtolower($topic)==='suggested extraction'){$topic='Coverage requirement';}$type='documentation';if(preg_match('/\beligible|eligibility|covered|coverage criteria\b/i',$statement)===1){$type='eligibility';}if(preg_match('/\bprior authorization|preauthorization|authorization required|pa required\b/i',$statement)===1){$type='prior_authorization';}if(preg_match('/\bfrequency|every \d+|per month|per year|replacement\b/i',$statement)===1){$type='frequency_limit';}$pa=preg_match('/\bprior authorization|preauthorization|authorization required|pa required\b/i',$statement)===1?'required':(preg_match('/\bno prior authorization|not required\b/i',$statement)===1?'not_required':'unknown');$forms=[];if(preg_match_all('/\b(?:form|forms?)\s+([A-Z0-9][A-Z0-9\- ]{1,40})/i',$statement,$matches)){foreach($matches[1] as$form){$forms[]=trim((string)$form," .;,");}}$forms=$forms===[]?$this->forms($input['required_forms']??$input['required_forms_text']??[]):array_values(array_unique(array_slice($forms,0,10)));return['payer'=>$payer,'plan_name'=>$this->text($input,'plan_name',191,false),'topic'=>$topic,'dme_category_slug'=>sanitize_title((string)($input['dme_category_slug']??$input['dme_category']??$topic)),'jurisdiction'=>$this->text($input,'jurisdiction',120,false),'requirement_type'=>$this->key($input['requirement_type']??$type,['documentation','eligibility','prior_authorization','frequency_limit','form','exception'],$type),'prior_authorization_status'=>$this->key($input['prior_authorization_status']??$pa,['required','not_required','conditional','unknown'],$pa),'frequency_limit'=>$this->noPhi($this->text($input,'frequency_limit',191,false)),'replacement_interval'=>$this->noPhi($this->text($input,'replacement_interval',191,false)),'required_forms'=>$forms,'coverage_criteria_text'=>$this->noPhi($this->text($input,'coverage_criteria_text',5000,false)),'requirement_text'=>$statement,'source_candidate_id'=>(string)($c['id']??''),'effective_date'=>$this->date($input['effective_date']??$c['document_effective_date']??null),'expires_at'=>$this->date($input['expires_at']??null)];}
private function pagesByNumber(array$pages):array{$out=[];foreach($pages as$page){$number=(int)($page['page_number']??0);if($number>0){$out[$number]=$page;}}return$out;}
private function requirementReadiness(array$r):array{$forms=$r['required_forms']??null;if($forms===null&&isset($r['required_forms_json'])){$decoded=json_decode((string)$r['required_forms_json'],true);$forms=is_array($decoded)?$decoded:[];}$forms=is_array($forms)?array_values(array_filter(array_map('strval',$forms))):[];$missing=[];$checks=['payer'=>(string)($r['payer']??''),'dme_category'=>(string)($r['dme_category_slug']??$r['topic']??''),'requirement_text'=>(string)($r['requirement_text']??''),'prior_authorization_status'=>(string)($r['prior_authorization_status']??'')];foreach($checks as$key=>$value){if(trim($value)===''||($key==='prior_authorization_status'&&$value==='unknown')){$missing[]=$key;}}if((string)($r['prior_authorization_status']??'unknown')==='required'&&$forms===[]){$missing[]='required_forms';}if(trim((string)($r['coverage_criteria_text']??''))===''){$missing[]='coverage_criteria';}return['ready'=>$missing===[],'missing'=>$missing,'required_forms'=>$forms,'prior_authorization_required'=>(string)($r['prior_authorization_status']??'unknown')==='required','summary'=>$missing===[]?'Ready for DME requirement use':'Missing '.implode(', ',$missing)];}
private function priorAuthorizationWorkup(array$r,array$readiness):array{$status=(string)($r['prior_authorization_status']??'unknown');$forms=is_array($readiness['required_forms']??null)?$readiness['required_forms']:[];$gaps=is_array($readiness['missing']??null)?$readiness['missing']:[];$tasks=[];$next='Confirm prior authorization requirement before scheduling.';if($status==='not_required'){$next='Prior authorization is not required by this requirement.';$tasks[]='Verify eligibility and document payer reference.';}elseif($status==='required'){$next=$gaps===[]?'Ready to assemble prior authorization submission materials.':'Resolve missing requirement details before assembling authorization materials.';$tasks[]='Collect signed order and clinical documentation per requirement text.';foreach($forms as$form){$tasks[]='Prepare required form: '.$form.'.';}if(trim((string)($r['coverage_criteria_text']??''))!==''){$tasks[]='Compare documentation against coverage criteria.';}}elseif($status==='conditional'){$next='Review coverage criteria to decide whether authorization is needed.';$tasks[]='Check condition triggers in coverage criteria.';}else{$tasks[]='Confirm prior authorization status from payer source.';}return['status'=>$status,'authorization_required'=>$status==='required','ready_for_submission_prep'=>$status==='required'&&$gaps===[],'next_action'=>$next,'blocking_gaps'=>$gaps,'staff_tasks'=>$tasks,'required_forms'=>$forms,'external_submission'=>false,'phi_allowed'=>false];}
private function checklistItems(string$text):array{$lines=preg_split('/\R+|(?<=[.;])\s+/',trim($text))?:[];$items=[];foreach($lines as$line){$line=trim($line," \t\n\r\0\x0B-•*");if($line!==''){$label=substr($line,0,220);$items[]=['hash'=>hash('sha256',$label),'label'=>$label,'status'=>'needed','notes'=>''];}}if($items===[]){$label=substr(trim($text),0,220);$items[]=['hash'=>hash('sha256',$label),'label'=>$label,'status'=>'needed','notes'=>''];}return$items;}
private function applyChecklistState(string$id,array$items,array$state):array{foreach($items as&$item){$saved=$state[$id.':'.(string)$item['hash']]??null;if(is_array($saved)){$item['status']=(string)($saved['status']??$item['status']);$item['notes']=(string)($saved['notes']??'');$item['updated_at']=(string)($saved['updated_at']??'');}}unset($item);return$items;}
private function reviewLanes(array$requirements):array{$lanes=['draft'=>0,'in_review'=>0,'published'=>0,'retired'=>0,'needs_source_review'=>0,'stale_or_expiring'=>0];foreach($requirements as$r){$status=(string)($r['review_status']??'draft');if(isset($lanes[$status])){$lanes[$status]++;}if((string)($r['source_review_status']??'current')==='needs_source_review'){$lanes['needs_source_review']++;}$expires=(string)($r['expires_at']??'');if($expires!==''&&$expires<=gmdate('Y-m-d',strtotime('+30 days'))){$lanes['stale_or_expiring']++;}}return$lanes;}
private function freshnessAlerts(array$requirements,array$documents):array{$alerts=[];$soon=gmdate('Y-m-d',strtotime('+30 days'));foreach($requirements as$r){$expires=(string)($r['expires_at']??'');if($expires!==''&&$expires<gmdate('Y-m-d')){$alerts[]=['type'=>'requirement_expired','label'=>(string)($r['payer']??'').' - '.(string)($r['topic']??''),'date'=>$expires];}elseif($expires!==''&&$expires<=$soon){$alerts[]=['type'=>'requirement_expiring','label'=>(string)($r['payer']??'').' - '.(string)($r['topic']??''),'date'=>$expires];}}foreach($documents as$d){if((string)($d['extraction_status']??'')==='stale'){$alerts[]=['type'=>'source_stale','label'=>(string)($d['publisher']??'').' - '.(string)($d['title']??''),'date'=>(string)($d['last_checked_at']??'')];}}return$alerts;}
